242: export function buildClaudeProcessEnv(input?: {
243:   readonly env?: NodeJS.ProcessEnv;
244:   readonly homeDir?: string;
245:   readonly hasClaudeCliCredentials?: boolean;
246:   readonly preserveDirectCredentialKeys?: ReadonlySet<string>;
247: }): NodeJS.ProcessEnv {
248:   const env = { ...(input?.env ?? process.env) };
249:   if (input?.homeDir) {
250:     env.HOME = input.homeDir;
251:   }
252:   const credentialInput = input?.homeDir ? { env, homeDir: input.homeDir } : { env };
253:   const hasLocalClaudeAuth =
254:     input?.hasClaudeCliCredentials ?? hasUsableClaudeCliCredentials(credentialInput);
255: 
256:   if (!hasLocalClaudeAuth || hasClaudeExternalAuthEnv(env)) {
257:     return buildProviderChildEnvironment({ provider: "claude", baseEnv: env });
258:   }
259: 
260:   // Claude gives direct request credentials precedence over local OAuth. Drop stale
261:   // app-process keys when a real Claude CLI login can satisfy the subprocess.
262:   for (const key of CLAUDE_DIRECT_CREDENTIAL_ENV_KEYS) {
263:     if (input?.preserveDirectCredentialKeys?.has(key)) {
264:       continue;
265:     }
266:     delete env[key];
267:   }
268:   return buildProviderChildEnvironment({ provider: "claude", baseEnv: env });
